import {expect,it} from 'vitest'
import {ActivitySession} from './activity-session'
const sha='a'.repeat(64),job='b'.repeat(64),pack='c'.repeat(32)
const track=(id:string):any=>({id,duration:120,reportId:'r',provenance:{runId:'run',masterSha256:sha,reportSha256:sha,vocalSha256:sha},native:{url:'/listen/media/'+id+'.flac',sha256:sha,bytes:20,duration:120},audioSegments:[]})
const a=track('a'),b=track('b')
function manifest():any{const sourceProof:any={};for(const [side,t] of [['a',a],['b',b]])sourceProof[side as string]={trackId:t.id,runId:'run',reportSha256:sha,assets:{master:{sha256:sha},vocals:{sha256:sha}}};return{schema:'harbeat.activity-set.v1',packId:pack,state:'ready',trackIds:['a','b'],initialTrackId:'a',sourceFingerprints:[track('a'),track('b')],results:[{schema:'harbeat.metric-mix-result.v1',id:job,status:'ready',policyVersion:'metric-mix-v1.0',codeVersion:sha,sourceProof,plan:{from:'a',to:'b',windowId:'w',start:30,end:34,duration:4,rate:1,bStart:2,bEnd:6,beatErrorMs:0},decision:{recommended:'original',methods:{original:{eligible:true}}},assets:{original:{url:`/listen/set-media/${pack}/${job}/original.wav`,sha256:sha,bytes:100,duration:4}}}]}}
it('reuses only identical source-bound cue, ignoring changed publication URL',async()=>{const s=await ActivitySession.open(manifest(),'活动',async id=>({...track(id),native:{...track(id).native,url:'/listen/catalog/new/media/x.flac'}}));expect(s.find(a,b,{start:30,end:34,rate:1,window:{id:'w',start:2,end:6}} as any)?.id).toBe(job);expect(s.find(a,b,{start:31,end:35,rate:1,window:{id:'w',start:2,end:6}} as any)).toBe(null);expect(s.ids.has('x')).toBe(false)})
it('rejects stale sources, cross-pack URLs and forged source proofs',async()=>{for(const mutate of [(m:any)=>m.sourceFingerprints[0].provenance.runId='old',(m:any)=>m.results[0].assets.original.url='/listen/smart-media/'+job+'/original.wav',(m:any)=>m.results[0].sourceProof.a.assets.master.sha256='d'.repeat(64)]){const m=manifest();mutate(m);await expect(ActivitySession.open(m,'活动',async id=>track(id))).rejects.toThrow()}})
